// A tiny fake "server" for the async exercises. Every call takes a few milliseconds,
// like a real API call. Do not edit this file.

export type Product = { id: number; name: string; price: number; inStock: boolean; category: string };

const products: Product[] = [
  { id: 1, name: 'Claw Hammer', price: 11.48, inStock: true, category: 'Hammer' },
  { id: 2, name: 'Thor Hammer', price: 11.14, inStock: false, category: 'Hammer' },
  { id: 3, name: 'Combination Pliers', price: 14.15, inStock: true, category: 'Pliers' },
  { id: 4, name: 'Long Nose Pliers', price: 14.24, inStock: false, category: 'Pliers' },
  { id: 5, name: 'Wood Saw', price: 12.18, inStock: true, category: 'Hand Saw' },
];

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/** Resolves with the product, or rejects with Error('Product <id> not found'). */
export async function getProduct(id: number): Promise<Product> {
  await wait(40);
  const product = products.find((p) => p.id === id);
  if (!product) throw new Error(`Product ${id} not found`);
  return { ...product };
}

/** Resolves with every product id. */
export async function listProductIds(): Promise<number[]> {
  await wait(40);
  return products.map((p) => p.id);
}
